export default function inspect({ file, fileId }) {
  const formats = {
    "application/pdf": "pdf",
    "application/epub+zip": "epub",
    "application/vnd.openxmlformats-officedocument.wordprocessingml.document": "docx",
    "text/plain": "txt",
    "text/md": "txt",
    "text/mdx": "txt",
    "text/markdown": "txt",
    "text/csv": "txt",
    "application/json": "txt",
  };
  if (
    !file ||
    file.fileId !== fileId ||
    typeof file.transitUrl !== "string" ||
    !file.transitUrl.startsWith("https://") ||
    typeof file.name !== "string" ||
    !Number.isInteger(file.sizeBytes) ||
    file.sizeBytes < 1 ||
    file.sizeBytes > 10000000 ||
    !formats[file.mimeType]
  )
    throw Error("Unsupported or invalid Drive file");
  const format = formats[file.mimeType];
  return { url: file.transitUrl, filename: file.name, format, convert: format !== "txt" };
}

