export default function select({ files, job }) {
  if (
    job?.status !== "finished" ||
    !Array.isArray(files) ||
    files.length !== 1 ||
    typeof files[0].url !== "string" ||
    !files[0].url.startsWith("https://")
  )
    throw Error("Document conversion failed");
  return { url: files[0].url };
}

