import { Buffer } from "node:buffer";
export default async function chunks({ url }, context) {
  const response = await context.fetch(url, { method: "GET" });
  if (!response.ok) throw Error("Document text download failed");
  const text = await response.text();
  if (!text.trim() || Buffer.byteLength(text, "utf8") > 500000)
    throw Error("Empty or oversized document text");
  const chunks = [];
  let chunk = "",
    size = 0;
  for (const char of text) {
    const n = Buffer.byteLength(char, "utf8");
    if (size + n > 3000) {
      chunks.push(chunk);
      chunk = "";
      size = 0;
    }
    chunk += char;
    size += n;
  }
  if (chunk) chunks.push(chunk);
  if (chunks.length > 200) throw Error("Too many chunks");
  return { chunks };
}

