export default function next({ chunks, previousState, summary }) {
  if (!Array.isArray(chunks) || !chunks.length || chunks.length > 200)
    throw Error("Invalid chunks");
  const prev = previousState ?? { index: 0, summaries: [] },
    summaries = prev.summaries.slice();
  let index = prev.index;
  if (previousState) {
    if (typeof summary !== "string" || !summary.trim()) throw Error("Empty chunk summary");
    summaries.push(summary);
    index++;
  }
  if (index > chunks.length || summaries.length !== index) throw Error("Invalid progress");
  const combined = summaries.map((s, i) => `Part ${i + 1}: ${s}`).join("\n\n");
  if (combined.length > 150000) throw Error("Combined summaries too large");
  return {
    state: { index, summaries },
    more: index < chunks.length,
    chunk: index < chunks.length ? chunks[index] : "",
    combined,
  };
}
